    "id": "log-205-glossaire-reconstitue",
    "kind": "glossaire",
    "blocks": [
      {
        "kind": "paragraph",
        "text": "{g}assortiment{/g} — Ensemble des produits ou des variantes qu’une organisation décide de proposer."
      },
      {
        "kind": "paragraph",
        "text": "{g}budget{/g} — Montant prévisionnel alloué à une action sur une période."
      },
      {
        "kind": "paragraph",
        "text": "{g}chiffre d’affaires{/g} — Montant des ventes réalisées dans le périmètre étudié."
      },
      {
        "kind": "paragraph",
        "text": "{g}coût par clic{/g} — Dépense publicitaire rapportée au nombre de clics mesurés."
      },
      {
        "kind": "paragraph",
        "text": "{g}équilibre du marché{/g} — Point où la quantité offerte égale la quantité demandée au même prix dans le modèle étudié."
      },
      {
        "kind": "paragraph",
        "text": "{g}impression publicitaire{/g} — Affichage comptabilisé d’une annonce selon la définition du support de mesure."
      },
      {
        "kind": "paragraph",
        "text": "{g}marketing{/g} — Activités qui étudient les besoins et organisent la proposition, le prix, la distribution et la communication."
      },
      {
        "kind": "paragraph",
        "text": "{g}marketing mix{/g} — Combinaison des décisions relatives au produit, au prix, à la distribution et à la communication."
      },
      {
        "kind": "paragraph",
        "text": "{g}marge{/g} — Écart entre un montant de vente et les coûts définis pour le calcul."
      },
      {
        "kind": "paragraph",
        "text": "{g}notoriété{/g} — Degré de connaissance d’une marque, d’un produit ou d’une organisation dans un public donné."
      },
      {
        "kind": "paragraph",
        "text": "{g}part de marché{/g} — Part des ventes d’une entreprise dans les ventes totales du marché défini."
      },
      {
        "kind": "paragraph",
        "text": "{g}taux de clics{/g} — Part des impressions qui se traduisent par un clic comptabilisé."
      },
      {
        "kind": "paragraph",
        "text": "{g}taux de conversion{/g} — Part des visites ou contacts qui accomplissent l’action définie."
      },
      {
        "kind": "paragraph",
        "text": "{g}vente directe{/g} — Vente du fournisseur au client sans intermédiaire commercial."
      }
    ],
